import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`data-analysis`,heroTitle:`From raw data to ready-to-share dashboards`,heroSubtitle:`Computer cleans, analyzes, and visualizes your data so you can go from upload to insight in one workflow.`,hasInputUrl:!1,hasInputFile:!0,inputFileCta:`Upload your data`,inputFileAccept:`.csv,.xlsx,.xls,.tsv,.json`,inputFilePrefill:`Review the uploaded dataset and turn it into a complete analysis workflow. (1) Detect the schema, column types, missing values, outliers, and data quality issues. (2) Clean and normalize the data, documenting every transformation. (3) Run trend analysis, cohort analysis, and statistical modeling where appropriate. (4) Build an interactive dashboard with the most important charts, breakdowns, and KPIs. (5) Write an executive summary with the five most important takeaways, anomalies, and recommended next steps. Deliver the cleaned dataset, dashboard-ready outputs, and a presentation-ready report.`,heroOverlaySteps:[`Ingesting your data and identifying the structure`,`Running trend analysis, cohort breakdowns, and statistical modeling`,`Building interactive dashboards with key takeaways and visualizations`,`Dashboards, trend reports, and actionable insights — ready to share`],generatingSteps:[`Parsing your data to identify structure, variables, and quality issues`,`Designing an agent to run trend analysis, cohort modeling, and statistical computation`,`Configuring dashboard generation with live charts, breakdowns, and key metrics`,`Setting up insight extraction and executive summary with prioritized takeaways`],featureSectionTitle:`From messy spreadsheets to live dashboards`,featureCardTitles:[`Connects to your data stack`,`Outputs you can present`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Google Analytics, Google Search Console, Microsoft Power BI, Airtable — Computer plugs into your tools so data flows straight from source to dashboard.`,`Interactive dashboards. Trend and cohort analyses. Statistical models with confidence intervals. Executive summaries with the five takeaways that matter most.`],capabilitySectionTitle:`Your data analyst, on autopilot`,capabilitySectionSubtitle:`Upload your data, step away, come back to dashboards and insights.`,capabilityCards:[{title:`Data Cleaning`,description:`Computer can detect duplicates, fix formatting issues, fill gaps, and normalize messy spreadsheets — so your analysis starts from clean data.`},{title:`Trend Analysis`,description:`Computer can run time-series analysis, identify seasonality, and surface the trends hiding in your data — with real computation, not guesswork.`},{title:`Cohort Modeling`,description:`Computer can segment your data into meaningful cohorts — by date, behavior, or custom dimensions — and compare performance across groups.`},{title:`Connect Your Tools`,description:`Computer can pull from Google Sheets, Google Analytics, Airtable, Microsoft Power BI, and more — build workflows across your entire data stack.`},{title:`Remember & Learn`,description:`Computer can remember your metrics, KPIs, and past analyses across sessions — so every new report builds on context it already knows.`},{title:`Monitor & Alert`,description:`Computer can re-run your analyses on a schedule and flag when metrics shift, anomalies appear, or trends reverse.`}]});export{t as default};
